import {formatMeasurement,unitInfo} from './units.mjs?v=20261024';
import {edgeBands,dimensionsText} from './workspace.mjs?v=20261024';
export function escapeHTML(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function pieceColors(index){return [['#d8e6f7','#6787b4'],['#e4def3','#9180b6'],['#f4e3cd','#b79b72'],['#dcebe1','#789c87'],['#f3dde2','#b0808c'],['#dcebed','#7da0a7'],['#e9e6d7','#a39a75'],['#e1e1ed','#9090b4']][index%8];}
export function sheetSVG(sheet,project,options={}){
 const o={labels:true,dimensions:true,colors:true,cuts:false,offcuts:true,fontScale:1,rotation:0,interactive:false,prefix:'sheet',selected:null,...options};
 const esc=escapeHTML,settings=project.settings,fmt=n=>formatMeasurement(n,settings.unit,settings.precision);
 const pad=Math.max(sheet.length,sheet.width)*.065,font=Math.max(sheet.length,sheet.width)*.013*o.fontScale,t=settings.trim||0;
 const angle=((o.rotation%360)+360)%360,turned=angle===90||angle===270;
 const transforms={0:'',90:`translate(${sheet.width} 0) rotate(90)`,180:`translate(${sheet.length} ${sheet.width}) rotate(180)`,270:`translate(0 ${sheet.length}) rotate(270)`};
 const pieces=sheet.parts.map(p=>{const [fill,stroke]=pieceColors(p.color||0),fs=Math.min(font,Math.min(p.w,p.h)*.15),key=`${p.id}:${p.copy}`,originalBands=edgeBands(p),bands=p.rotated?Object.fromEntries(Object.entries(originalBands).map(([side,name])=>[{T:'R',R:'B',B:'L',L:'T'}[side],name])):originalBands;
 const label=p.label||`Part ${(p.color||0)+1}`;const shortLabel=label.length>28?label.slice(0,26)+'…':label;const lines=[...(o.labels?[shortLabel]:[]),...(o.dimensions?[dimensionsText(p.w,p.h,settings)+(p.rotated?' ↻':'')]:[])];
 return `<g ${o.interactive?`data-piece="${esc(key)}" tabindex="0" role="button" aria-label="${esc(label)}, ${esc(dimensionsText(p.length,p.width,settings))}"`:''} class="piece ${o.selected===key?'selected':''}"><title>${esc(label)} · ${esc(dimensionsText(p.length,p.width,settings))}${Object.entries(originalBands).map(([side,name])=>` · ${side}: ${esc(name)}`).join('')}</title><rect x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}" fill="${o.colors?fill:'#fff'}" stroke="${stroke}" stroke-width="${Math.max(sheet.length,sheet.width)*.0006}"/>${Object.entries(bands).filter(([,name])=>name).map(([side])=>`<path d="${{T:`M${p.x} ${p.y}h${p.w}`,B:`M${p.x} ${p.y+p.h}h${p.w}`,L:`M${p.x} ${p.y}v${p.h}`,R:`M${p.x+p.w} ${p.y}v${p.h}`}[side]}" stroke="${stroke}" stroke-width="${Math.min(p.w,p.h)*.025}"/>`).join('')}${lines.map((line,i)=>`<text x="${p.x+p.w/2}" y="${p.y+p.h/2+(i-(lines.length-1)/2)*fs*1.5}" fill="#35465c" dominant-baseline="middle" text-anchor="middle" font-size="${Math.min(fs,p.w/(Math.max(1,line.length)*.6))}">${esc(line)}</text>`).join('')}${p.grain&&p.grain!==false&&p.grain!=='none'?`<text x="${p.x+p.w/2}" y="${p.y+p.h*.2}" text-anchor="middle" fill="${stroke}" font-size="${fs}">${(p.rotated?(p.grain==='width'?'length':'width'):p.grain)==='width'?'↕':'↔'}</text>`:''}</g>`;
 }).join('');
 const offcuts=o.offcuts?sheet.free.map(f=>{const fs=Math.min(font*.7,f.h*.18,f.w*.12);return `<rect x="${f.x}" y="${f.y}" width="${f.w}" height="${f.h}" fill="url(#${o.prefix}-hatch)"/><text x="${f.x+f.w/2}" y="${f.y+f.h/2}" text-anchor="middle" fill="#687586" font-size="${fs}">${esc(dimensionsText(f.w,f.h,settings))}</text>`;}).join(''):'';
 const cuts=o.cuts?sheet.cuts.map((c,i)=>`<g><path d="M${c.x} ${c.y}${c.axis==='vertical'?'v':'h'}${c.length}" stroke="#d85941" stroke-width="${font*.13}" stroke-dasharray="${font*.5} ${font*.3}"/><circle cx="${c.x}" cy="${c.y}" r="${font*.65}" fill="#d85941"/><text x="${c.x}" y="${c.y}" font-size="${font*.75}" fill="white" dominant-baseline="middle" text-anchor="middle">${i+1}</text></g>`).join(''):'';
 return `<svg xmlns="http://www.w3.org/2000/svg" class="sheet-svg" viewBox="${-pad} ${-pad} ${(turned?sheet.width:sheet.length)+2*pad} ${(turned?sheet.length:sheet.width)+2*pad}" role="${o.interactive?'group':'img'}" aria-label="Cutting layout for ${esc(sheet.label||'stock')}"><defs><pattern id="${o.prefix}-hatch" width="${font}" height="${font}" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="${font}" height="${font}" fill="#f6f7f9"/><path d="M0 0v${font}" stroke="#dce2eb" stroke-width="${font*.08}"/></pattern></defs><style>text{font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif}.selected rect{stroke:#1769e0;stroke-width:${font*.25}}</style><g transform="${transforms[angle]}"><rect width="${sheet.length}" height="${sheet.width}" fill="#f3f5f8" stroke="#aab7c8" stroke-width="${font*.12}"/>${t?`<rect x="${t}" y="${t}" width="${sheet.length-2*t}" height="${sheet.width-2*t}" fill="none" stroke="#9eabbc" stroke-dasharray="${font}"/>`:''}${offcuts}${pieces}${cuts}<text x="${sheet.length/2}" y="${-pad*.4}" fill="#65748a" text-anchor="middle" font-size="${font*.85}">${esc(fmt(sheet.length))} ${unitInfo(settings.unit).label}</text><text transform="translate(${-pad*.4} ${sheet.width/2}) rotate(-90)" fill="#65748a" text-anchor="middle" font-size="${font*.85}">${esc(fmt(sheet.width))} ${unitInfo(settings.unit).label}</text></g></svg>`;
}
